-- ZAQVION LABS foundation. Apply through Supabase CLI after configuring a project.
create table if not exists profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'customer' check (role in ('customer','admin')), full_name text, created_at timestamptz not null default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, category text not null check(category in ('Hardware','Software')), summary text not null, status text not null default 'draft' check(status in ('draft','published')), created_at timestamptz not null default now());
create table if not exists enquiries (id uuid primary key default gen_random_uuid(), reference text unique not null, customer_id uuid references profiles(id), project_id uuid references projects(id), full_name text not null, contact text not null, requirements text not null, created_at timestamptz not null default now());
create table if not exists favourites (customer_id uuid references profiles(id) on delete cascade, project_id uuid references projects(id) on delete cascade, created_at timestamptz not null default now(), primary key(customer_id,project_id));
create table if not exists reviews (id uuid primary key default gen_random_uuid(), customer_id uuid references profiles(id), rating int check(rating between 1 and 5), feedback text not null, status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now());
create table if not exists project_orders (id uuid primary key default gen_random_uuid(), customer_id uuid not null references profiles(id), project_id uuid references projects(id), status text not null default 'Enquiry Received', progress int not null default 0 check(progress between 0 and 100), created_at timestamptz not null default now());
create table if not exists project_updates (id uuid primary key default gen_random_uuid(), order_id uuid not null references project_orders(id) on delete cascade, description text not null, created_at timestamptz not null default now());
alter table profiles enable row level security; alter table favourites enable row level security; alter table enquiries enable row level security; alter table project_orders enable row level security; alter table project_updates enable row level security;
create policy "profiles own" on profiles for select using (auth.uid()=id); create policy "favourites own" on favourites for all using (auth.uid()=customer_id) with check (auth.uid()=customer_id); create policy "enquiries own" on enquiries for select using (auth.uid()=customer_id); create policy "orders own" on project_orders for select using (auth.uid()=customer_id); create policy "updates for own orders" on project_updates for select using (exists(select 1 from project_orders o where o.id=order_id and o.customer_id=auth.uid()));
